graphql.query:
query Rooms {
  rooms {
    roomCode
    name
    building
    seats
  }
}

query Slots($roomCode: String!, $date: String!) {
  slots(roomCode: $roomCode, date: $date) {
    id
    roomCode
    date
    startHour
    seats
    booked
    seatsLeft
  }
}

mutation BookSlot($regNo: String!) {
  bookSlot(regNo: $regNo, slotId: "{{slotId}}") {
    slotId
    roomCode
    roomName
    date
    startHour
  }
}

query Dashboard($regNo: String!, $roomCode: String!, $date: String!) {
  student(regNo: $regNo) {
    regNo
    name
    email
    bookings {
      slotId
      roomName
      roomCode
      date
      startHour
    }
  }
  rooms {
    roomCode
    name
    building
    seats
  }
  slots(roomCode: $roomCode, date: $date) {
    id
    startHour
    seats
    booked
    seatsLeft
  }
}
